const body = $json.body?.toLowerCase() || '';
const subject = $json.subject || '';
const source = subject.includes('zelle') ? 'Zelle'
  : subject.includes('venmo') ? 'Venmo'
  : subject.includes('paypal') ? 'PayPal'
  : 'Other';

const amountMatch = body.match(/\$\s?\d{1,3}(?:,\d{3})*(?:\.\d{2})?/);
const dateMatch = body.match(/\b\d{1,2}\/\d{1,2}\/\d{2,4}\b/);

return [{
  json: {
    date: dateMatch ? dateMatch[0] : new Date().toLocaleDateString(),
    amount: amountMatch ? amountMatch[0] : "Not found",
    source,
    subject,
    snippet: body.slice(0, 250)
  }
}];
